/**
 * D-OS Terminal Canvas Chart Engine
 * Lightweight, zero-dependency high-DPI canvas renderer with Chart.js compatible API.
 */
(function (global) {
  "use strict";

  function toNum(v) {
    var n = Number(v);
    return isNaN(n) ? 0 : n;
  }

  function formatCurrency(val) {
    var n = Math.abs(val);
    var sign = val < 0 ? "-" : "";
    if (n >= 10000000) return sign + "₹" + (n / 10000000).toFixed(1) + "Cr";
    if (n >= 100000) return sign + "₹" + (n / 100000).toFixed(1) + "L";
    if (n >= 1000) return sign + "₹" + Math.round(n / 1000) + "k";
    return sign + "₹" + Math.round(n);
  }

  function scaleBounds(minVal, maxVal) {
    minVal = toNum(minVal);
    maxVal = toNum(maxVal);
    if (minVal > 0) minVal = 0;
    if (maxVal < 0) maxVal = 0;
    if (minVal === maxVal) {
      var base = Math.abs(maxVal || 100);
      minVal -= base * 0.2;
      maxVal += base * 0.2;
    }
    var range = maxVal - minVal;
    var pad = range * 0.12;
    return {
      min: minVal - pad,
      max: maxVal + pad,
      range: range + pad * 2
    };
  }

  var DEFAULT_COLORS = [
    "#66FF99",
    "#ff5577",
    "#33ccff",
    "#ffe66d",
    "#ff4fd8",
    "#9b5cff",
    "#4faf70",
    "#ff9966",
    "#66ccff",
    "#ffcc00"
  ];

  function Chart(canvas, config) {
    if (!canvas) return;
    this.canvas = typeof canvas === "string" ? document.getElementById(canvas) : canvas;
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext("2d");
    this.config = config || {};
    this.type = this.config.type || "bar";
    this.data = this.config.data || { labels: [], datasets: [] };
    this.options = this.config.options || {};
    this.hoverIndex = -1;
    this.hoverDataset = -1;
    this.tooltipPos = null;

    this._onResize = this._onResize.bind(this);
    this._onMouseMove = this._onMouseMove.bind(this);
    this._onMouseLeave = this._onMouseLeave.bind(this);

    window.addEventListener("resize", this._onResize);
    this.canvas.addEventListener("mousemove", this._onMouseMove);
    this.canvas.addEventListener("mouseleave", this._onMouseLeave);

    this.draw();
  }

  Chart.prototype.destroy = function () {
    window.removeEventListener("resize", this._onResize);
    if (this.canvas) {
      this.canvas.removeEventListener("mousemove", this._onMouseMove);
      this.canvas.removeEventListener("mouseleave", this._onMouseLeave);
      if (this.ctx) {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      }
      this.canvas.chartInstance = null;
    }
  };

  Chart.prototype._onResize = function () {
    this.draw();
  };

  Chart.prototype._onMouseMove = function (evt) {
    var rect = this.canvas.getBoundingClientRect();
    var x = evt.clientX - rect.left;
    var y = evt.clientY - rect.top;
    this.tooltipPos = { x: x, y: y };
    this.draw();
  };

  Chart.prototype._onMouseLeave = function () {
    this.tooltipPos = null;
    this.hoverIndex = -1;
    this.hoverDataset = -1;
    this.draw();
  };

  Chart.prototype.resize = function () {
    var rect = this.canvas.getBoundingClientRect();
    var dpr = window.devicePixelRatio || 1;
    var width = rect.width > 0 ? rect.width : (this.canvas.parentElement ? this.canvas.parentElement.clientWidth : 400);
    var height = rect.height > 0 ? rect.height : 260;
    this.canvas.width = Math.floor(width * dpr);
    this.canvas.height = Math.floor(height * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { width: width, height: height };
  };

  Chart.prototype.draw = function () {
    var size = this.resize();
    var w = size.width;
    var h = size.height;
    var ctx = this.ctx;
    var labels = this.data.labels || [];
    var datasets = this.data.datasets || [];

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = "#020804";
    ctx.fillRect(0, 0, w, h);

    var hasData = false;
    for (var di = 0; di < datasets.length; di++) {
      var arr = datasets[di].data || [];
      for (var k = 0; k < arr.length; k++) {
        if (toNum(arr[k]) !== 0) {
          hasData = true;
          break;
        }
      }
      if (hasData) break;
    }

    if (!labels.length || !datasets.length || !hasData) {
      this._drawEmpty(w, h, "NO DATA AVAILABLE");
      return;
    }

    if (this.type === "doughnut" || this.type === "pie") {
      this._drawDoughnut(w, h, labels, datasets);
    } else if (this.type === "line") {
      this._drawLine(w, h, labels, datasets);
    } else {
      this._drawBar(w, h, labels, datasets);
    }

    this._drawLegend(w, h, datasets, labels);
  };

  Chart.prototype._scaleTitle = function (axis) {
    var scales = this.options && this.options.scales ? this.options.scales : {};
    return scales[axis] && scales[axis].title ? scales[axis].title.text || "" : "";
  };

  Chart.prototype._drawEmpty = function (w, h, msg) {
    var ctx = this.ctx;
    ctx.fillStyle = "#4faf70";
    ctx.font = "16px 'VT323', monospace";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("[ " + (msg || "NO FINANCIAL DATA") + " ]", w / 2, h / 2);
  };

  Chart.prototype._drawLegend = function (w, h, datasets, labels) {
    if (this.type === "doughnut" || this.type === "pie") return;
    if (!datasets || datasets.length <= 1) return;
    var ctx = this.ctx;
    ctx.font = "15px 'VT323', monospace";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    var startX = 60;
    var curX = startX;
    var topY = 6;
    for (var i = 0; i < datasets.length; i++) {
      var ds = datasets[i];
      var color = ds.borderColor || ds.backgroundColor || DEFAULT_COLORS[i % DEFAULT_COLORS.length];
      var label = ds.label || "Dataset " + (i + 1);
      ctx.fillStyle = Array.isArray(color) ? color[0] : color;
      ctx.fillRect(curX, topY + 2, 10, 10);
      ctx.fillStyle = "#e5ffe9";
      ctx.fillText(label, curX + 14, topY);
      curX += ctx.measureText(label).width + 30;
    }
  };

  Chart.prototype._drawBar = function (w, h, labels, datasets) {
    var ctx = this.ctx;
    var padLeft = 68;
    var padRight = 24;
    var padTop = datasets.length > 1 ? 32 : 18;
    var padBottom = this._scaleTitle("x") ? 54 : 38;
    var plotW = w - padLeft - padRight;
    var plotH = h - padTop - padBottom;

    if (plotW <= 0 || plotH <= 0) return;

    var maxVal = 0;
    var minVal = 0;
    for (var d = 0; d < datasets.length; d++) {
      var data = datasets[d].data || [];
      for (var i = 0; i < data.length; i++) {
        var val = toNum(data[i]);
        if (val > maxVal) maxVal = val;
        if (val < minVal) minVal = val;
      }
    }
    var bounds = scaleBounds(minVal, maxVal);
    var zeroY = padTop + ((bounds.max - 0) / bounds.range) * plotH;

    // Gridlines & Ticks
    ctx.strokeStyle = "rgba(102, 255, 153, 0.12)";
    ctx.lineWidth = 1;
    ctx.fillStyle = "#4faf70";
    ctx.font = "14px 'VT323', monospace";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";

    var gridSteps = 4;
    for (var s = 0; s <= gridSteps; s++) {
      var gy = padTop + (plotH / gridSteps) * s;
      var gVal = bounds.max - (bounds.range / gridSteps) * s;
      ctx.beginPath();
      ctx.moveTo(padLeft, gy);
      ctx.lineTo(w - padRight, gy);
      ctx.stroke();
      ctx.fillText(formatCurrency(gVal), padLeft - 8, gy);
    }

    // Axes
    ctx.strokeStyle = "rgba(102, 255, 153, 0.35)";
    ctx.beginPath();
    ctx.moveTo(padLeft, padTop);
    ctx.lineTo(padLeft, padTop + plotH);
    ctx.lineTo(w - padRight, padTop + plotH);
    ctx.stroke();

    if (zeroY >= padTop && zeroY <= padTop + plotH) {
      ctx.strokeStyle = "rgba(229, 255, 233, 0.28)";
      ctx.beginPath();
      ctx.moveTo(padLeft, zeroY);
      ctx.lineTo(w - padRight, zeroY);
      ctx.stroke();
    }

    var numLabels = Math.max(1, labels.length);
    var groupW = plotW / numLabels;
    var numDs = Math.max(1, datasets.length);
    var maxBarWidth = 56;
    var barW = Math.min(maxBarWidth, Math.max(10, (groupW * 0.65) / numDs));

    var hoveredVal = null;
    var hoveredLabel = "";

    for (var li = 0; li < labels.length; li++) {
      var gx = padLeft + li * groupW;
      var groupCenter = gx + groupW / 2;
      var groupTotalW = barW * numDs + (numDs - 1) * 4;
      var startBx = groupCenter - groupTotalW / 2;

      for (var di = 0; di < datasets.length; di++) {
        var ds = datasets[di];
        var val = toNum((ds.data || [])[li]);
        var valY = padTop + ((bounds.max - val) / bounds.range) * plotH;
        var bx = startBx + di * (barW + 4);
        var by = Math.min(valY, zeroY);
        var barH = Math.max(2, Math.abs(zeroY - valY));

        var color = Array.isArray(ds.backgroundColor)
          ? ds.backgroundColor[li % ds.backgroundColor.length]
          : ds.backgroundColor || DEFAULT_COLORS[di % DEFAULT_COLORS.length];

        ctx.fillStyle = color;
        ctx.fillRect(bx, by, barW, barH);

        // Subtle highlight line on bar top
        ctx.fillStyle = "rgba(255, 255, 255, 0.25)";
        ctx.fillRect(bx, by, barW, 2);

        if (
          this.tooltipPos &&
          this.tooltipPos.x >= bx &&
          this.tooltipPos.x <= bx + barW &&
          this.tooltipPos.y >= by &&
          this.tooltipPos.y <= by + barH
        ) {
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 2;
          ctx.strokeRect(bx - 1, by - 1, barW + 2, barH + 1);
          hoveredVal = val;
          hoveredLabel = labels[li] + (ds.label ? " · " + ds.label : "");
        }
      }

      // X-Axis Label
      ctx.fillStyle = "#77aa85";
      ctx.font = "14px 'VT323', monospace";
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      var lbl = String(labels[li] || "");
      if (lbl.length > 12) lbl = lbl.slice(0, 11) + "…";
      ctx.fillText(lbl, groupCenter, padTop + plotH + 8);
    }

    this._drawAxisTitles(w, h, padLeft, padTop, plotW, plotH);

    if (hoveredVal !== null && this.tooltipPos) {
      this._drawTooltip(hoveredLabel, "₹" + hoveredVal.toLocaleString("en-IN"));
    }
  };

  Chart.prototype._drawLine = function (w, h, labels, datasets) {
    var ctx = this.ctx;
    var padLeft = 68;
    var padRight = 24;
    var padTop = datasets.length > 1 ? 32 : 18;
    var padBottom = this._scaleTitle("x") ? 54 : 38;
    var plotW = w - padLeft - padRight;
    var plotH = h - padTop - padBottom;

    if (plotW <= 0 || plotH <= 0) return;

    var maxVal = 0;
    var minVal = 0;
    for (var d = 0; d < datasets.length; d++) {
      var data = datasets[d].data || [];
      for (var i = 0; i < data.length; i++) {
        var val = toNum(data[i]);
        if (val > maxVal) maxVal = val;
        if (val < minVal) minVal = val;
      }
    }
    var bounds = scaleBounds(minVal, maxVal);
    var zeroY = padTop + ((bounds.max - 0) / bounds.range) * plotH;

    // Gridlines & Ticks
    ctx.strokeStyle = "rgba(102, 255, 153, 0.12)";
    ctx.lineWidth = 1;
    ctx.fillStyle = "#4faf70";
    ctx.font = "14px 'VT323', monospace";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";

    var gridSteps = 4;
    for (var s = 0; s <= gridSteps; s++) {
      var gy = padTop + (plotH / gridSteps) * s;
      var gVal = bounds.max - (bounds.range / gridSteps) * s;
      ctx.beginPath();
      ctx.moveTo(padLeft, gy);
      ctx.lineTo(w - padRight, gy);
      ctx.stroke();
      ctx.fillText(formatCurrency(gVal), padLeft - 8, gy);
    }

    // Axes
    ctx.strokeStyle = "rgba(102, 255, 153, 0.35)";
    ctx.beginPath();
    ctx.moveTo(padLeft, padTop);
    ctx.lineTo(padLeft, padTop + plotH);
    ctx.lineTo(w - padRight, padTop + plotH);
    ctx.stroke();

    if (zeroY >= padTop && zeroY <= padTop + plotH) {
      ctx.strokeStyle = "rgba(229, 255, 233, 0.28)";
      ctx.beginPath();
      ctx.moveTo(padLeft, zeroY);
      ctx.lineTo(w - padRight, zeroY);
      ctx.stroke();
    }

    var numLabels = Math.max(1, labels.length);
    var stepX = numLabels > 1 ? plotW / (numLabels - 1) : 0;
    var hoveredVal = null;
    var hoveredLabel = "";

    for (var di = 0; di < datasets.length; di++) {
      var ds = datasets[di];
      var data = ds.data || [];
      var color = ds.borderColor || ds.backgroundColor || "#66FF99";
      var strokeColor = Array.isArray(color) ? color[0] : color;

      var points = [];
      for (var li = 0; li < labels.length; li++) {
        var val = toNum(data[li]);
        var px = numLabels === 1 ? padLeft + plotW / 2 : padLeft + li * stepX;
        var py = padTop + ((bounds.max - val) / bounds.range) * plotH;
        points.push({ x: px, y: py, val: val, label: labels[li] });
      }

      // Draw Gradient Fill Area Under Line
      if (points.length >= 2) {
        var grad = ctx.createLinearGradient(0, padTop, 0, padTop + plotH);
        grad.addColorStop(0, "rgba(102, 255, 153, 0.22)");
        grad.addColorStop(1, "rgba(102, 255, 153, 0.0)");
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(points[0].x, padTop + plotH);
        for (var pi = 0; pi < points.length; pi++) {
          ctx.lineTo(points[pi].x, points[pi].y);
        }
        ctx.lineTo(points[points.length - 1].x, padTop + plotH);
        ctx.closePath();
        ctx.fill();
      }

      // Draw Stroke Line
      ctx.strokeStyle = strokeColor;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      for (var pi = 0; pi < points.length; pi++) {
        if (pi === 0) ctx.moveTo(points[pi].x, points[pi].y);
        else ctx.lineTo(points[pi].x, points[pi].y);
      }
      ctx.stroke();

      // If single point, draw horizontal guide line
      if (points.length === 1) {
        ctx.strokeStyle = "rgba(102, 255, 153, 0.3)";
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(padLeft, points[0].y);
        ctx.lineTo(w - padRight, points[0].y);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      // Draw Data Node Points
      for (var pi = 0; pi < points.length; pi++) {
        var pt = points[pi];
        ctx.fillStyle = "#020804";
        ctx.strokeStyle = strokeColor;
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.arc(pt.x, pt.y, 4.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        if (
          this.tooltipPos &&
          Math.hypot(this.tooltipPos.x - pt.x, this.tooltipPos.y - pt.y) < 16
        ) {
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 2.5;
          ctx.beginPath();
          ctx.arc(pt.x, pt.y, 7, 0, Math.PI * 2);
          ctx.stroke();
          hoveredVal = pt.val;
          hoveredLabel = pt.label + (ds.label ? " · " + ds.label : "");
        }
      }
    }

    // X-Axis Labels
    ctx.fillStyle = "#77aa85";
    ctx.font = "14px 'VT323', monospace";
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    var step = Math.max(1, Math.ceil(labels.length / 8));
    for (var li = 0; li < labels.length; li += step) {
      var px = numLabels === 1 ? padLeft + plotW / 2 : padLeft + li * stepX;
      var lbl = String(labels[li] || "");
      if (lbl.length > 10) lbl = lbl.slice(0, 9) + "…";
      ctx.fillText(lbl, px, padTop + plotH + 8);
    }

    this._drawAxisTitles(w, h, padLeft, padTop, plotW, plotH);

    if (hoveredVal !== null && this.tooltipPos) {
      this._drawTooltip(hoveredLabel, "₹" + hoveredVal.toLocaleString("en-IN"));
    }
  };

  Chart.prototype._drawAxisTitles = function (w, h, padLeft, padTop, plotW, plotH) {
    var ctx = this.ctx;
    var xTitle = this._scaleTitle("x");
    var yTitle = this._scaleTitle("y");
    ctx.fillStyle = "#66FF99";
    ctx.font = "13px 'VT323', monospace";
    if (xTitle) {
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      ctx.fillText(xTitle, padLeft + plotW / 2, h - 4);
    }
    if (yTitle) {
      ctx.save();
      ctx.translate(13, padTop + plotH / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(yTitle, 0, 0);
      ctx.restore();
    }
  };

  Chart.prototype._drawDoughnut = function (w, h, labels, datasets) {
    var ctx = this.ctx;
    var data = (datasets[0] && datasets[0].data) || [];
    var total = 0;
    for (var i = 0; i < data.length; i++) {
      total += toNum(data[i]);
    }

    var cx = w / 2;
    var cy = h / 2;
    var radius = Math.min(w, h) / 2 - 20;
    var innerRadius = this.type === "doughnut" ? radius * 0.58 : 0;

    if (total <= 0 || radius <= 10) {
      this._drawEmpty(w, h, "NO DATA AVAILABLE");
      return;
    }

    var startAngle = -Math.PI / 2;
    var hoveredSlice = null;

    for (var di = 0; di < data.length; di++) {
      var val = toNum(data[di]);
      var sliceAngle = (val / total) * Math.PI * 2;
      var endAngle = startAngle + sliceAngle;

      var color =
        (datasets[0].backgroundColor && Array.isArray(datasets[0].backgroundColor) && datasets[0].backgroundColor[di]) ||
        DEFAULT_COLORS[di % DEFAULT_COLORS.length];

      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, radius, startAngle, endAngle);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();

      // Clean dark segment separator line
      ctx.strokeStyle = "#020804";
      ctx.lineWidth = 2;
      ctx.stroke();

      if (this.tooltipPos) {
        var dx = this.tooltipPos.x - cx;
        var dy = this.tooltipPos.y - cy;
        var dist = Math.sqrt(dx * dx + dy * dy);
        var angle = Math.atan2(dy, dx);
        if (angle < -Math.PI / 2) angle += Math.PI * 2;

        if (dist >= innerRadius && dist <= radius + 6) {
          if (angle >= startAngle && angle <= endAngle) {
            hoveredSlice = {
              label: labels[di] || "Item " + (di + 1),
              val: val,
              pct: Math.round((val / total) * 100) + "%"
            };
          }
        }
      }

      startAngle = endAngle;
    }

    if (this.type === "doughnut") {
      ctx.globalCompositeOperation = "destination-out";
      ctx.beginPath();
      ctx.arc(cx, cy, innerRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = "source-over";

      ctx.strokeStyle = "rgba(102, 255, 153, 0.25)";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(cx, cy, innerRadius, 0, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = "#66FF99";
      ctx.font = "bold 18px 'VT323', monospace";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(formatCurrency(total), cx, cy);
    }

    if (hoveredSlice && this.tooltipPos) {
      this._drawTooltip(hoveredSlice.label, "₹" + hoveredSlice.val.toLocaleString("en-IN") + " (" + hoveredSlice.pct + ")");
    }
  };

  Chart.prototype._drawTooltip = function (title, text) {
    if (!this.tooltipPos) return;
    var ctx = this.ctx;
    ctx.font = "15px 'VT323', monospace";
    var tw = Math.max(ctx.measureText(title).width, ctx.measureText(text).width) + 20;
    var th = 46;
    var tx = Math.min(this.canvas.width / (window.devicePixelRatio || 1) - tw - 10, Math.max(10, this.tooltipPos.x + 14));
    var ty = Math.max(10, this.tooltipPos.y - th - 10);

    ctx.fillStyle = "rgba(2, 8, 4, 0.96)";
    ctx.strokeStyle = "#66FF99";
    ctx.lineWidth = 1.5;
    ctx.fillRect(tx, ty, tw, th);
    ctx.strokeRect(tx, ty, tw, th);

    ctx.fillStyle = "#ffffff";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(title, tx + 10, ty + 6);

    ctx.fillStyle = "#66FF99";
    ctx.fillText(text, tx + 10, ty + 24);
  };

  global.Chart = Chart;
})(typeof window !== "undefined" ? window : this);

